<script setup>
import{ref}from'vue';import{useRoute,useRouter}from'vue-router';const route=useRoute(),router=useRouter(),form=ref({date_entretien:'',lieu_entretien:'',commentaire:''}),erreur=ref(''),enCours=ref(false);async function envoyer(){enCours.value=true;try{const r=await fetch(`/api/candidatures/${route.params.id}/entretiens`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});const d=await r.json();if(!r.ok)throw new Error(d.message);router.push({name:'entretien-confirme',params:{id:route.params.id},query:{entretien:d.id}})}catch(e){erreur.value=e.message}finally{enCours.value=false}}</script><template><main class="page"><button @click="router.back()">← Retour</button><h1>Créer un entretien</h1><form @submit.prevent="envoyer"><label>Date et heure<input v-model="form.date_entretien" type="datetime-local" required></label><label>Lieu<input v-model="form.lieu_entretien" required></label><label>Commentaire<textarea v-model="form.commentaire" rows="5"/></label><button :disabled="enCours">{{enCours?'Création…':'Valider l’entretien'}}</button></form><p>{{erreur}}</p></main></template><style scoped>.page{max-width:600px;margin:auto;padding:24px}.page form{display:grid;gap:14px}.page label{display:grid;gap:6px;font-weight:bold}.page input,.page textarea{padding:10px;font:inherit}.page form button{background:teal;color:#fff;border:0;padding:12px;border-radius:8px;font-weight:bold}</style>
